-- PostgreSQL 17: instalação nova. Não executar sobre schemas existentes.
-- Modelo: docs/architecture/SUMMARY_POSTGRESQL.md.
CREATE SCHEMA "RFFUSION_SUMMARY";
SET search_path TO "RFFUSION_SUMMARY", pg_catalog;

CREATE TABLE "SUMMARY_REFRESH_LOG" (
  "ID_REFRESH_LOG" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "NA_OBJECT_NAME" varchar(100) NOT NULL,
  "DT_STARTED_AT" timestamp without time zone NOT NULL,
  "DT_FINISHED_AT" timestamp without time zone DEFAULT NULL,
  "IS_SUCCESS" smallint NOT NULL DEFAULT 0,
  "NU_ROW_COUNT" bigint DEFAULT NULL,
  "NA_SOURCE_HIGH_WATERMARK" varchar(255) DEFAULT NULL,
  "NA_ERROR_MESSAGE" text DEFAULT NULL,
  PRIMARY KEY ("ID_REFRESH_LOG")
);

CREATE TABLE "SUMMARY_OUTBOX" (
  "ID_OUTBOX" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "NA_SCOPE_TYPE" varchar(32) NOT NULL,
  "NA_SCOPE_VALUE" varchar(64) NOT NULL,
  "NA_SOURCE_HANDLER" varchar(64) DEFAULT NULL,
  "NA_REASON" varchar(64) DEFAULT NULL,
  "DT_CREATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("ID_OUTBOX")
);

CREATE TABLE "SUMMARY_WORKER_STATE" (
  "NA_CONSUMER" varchar(64) NOT NULL,
  "ID_LAST_OUTBOX" bigint NOT NULL DEFAULT 0,
  "DT_LAST_START" timestamp without time zone DEFAULT NULL,
  "DT_LAST_END" timestamp without time zone DEFAULT NULL,
  "DT_LAST_SUCCESS" timestamp without time zone DEFAULT NULL,
  "DT_LAST_FAILURE" timestamp without time zone DEFAULT NULL,
  "NU_LAST_BATCH_SIZE" bigint NOT NULL DEFAULT 0,
  "NU_LAST_EVENT_COUNT" bigint NOT NULL DEFAULT 0,
  "NA_STATUS" varchar(32) NOT NULL DEFAULT 'idle',
  "NA_ERROR_MESSAGE" text DEFAULT NULL,
  PRIMARY KEY ("NA_CONSUMER")
);

CREATE TABLE "HOST_EQUIPMENT_LINK" (
  "FK_HOST" integer NOT NULL,
  "FK_EQUIPMENT" integer NOT NULL,
  "NA_MATCH_TYPE" varchar(32) NOT NULL,
  "VL_MATCH_CONFIDENCE" decimal(5,2) NOT NULL,
  "IS_PRIMARY_LINK" smallint NOT NULL DEFAULT 0 CHECK ("IS_PRIMARY_LINK" IN (0, 1)),
  PRIMARY KEY ("FK_HOST", "FK_EQUIPMENT")
);

CREATE TABLE "SITE_EQUIPMENT_METRIC" (
  "FK_SITE" integer NOT NULL,
  "FK_EQUIPMENT" integer NOT NULL,
  "DT_FIRST_SEEN_AT" timestamp without time zone,
  "DT_LAST_SEEN_AT" timestamp without time zone,
  "NU_SPECTRUM_COUNT" bigint NOT NULL CHECK ("NU_SPECTRUM_COUNT" >= 0),
  "ID_LAST_SPECTRUM" bigint,
  "DT_REFRESHED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("FK_SITE", "FK_EQUIPMENT")
);

CREATE TABLE "HOST_LOCATION_VISIT" (
  "FK_HOST" integer NOT NULL,
  "NU_VISIT" bigint NOT NULL,
  "FK_SITE" integer NOT NULL,
  "DT_FIRST_SEEN_AT" timestamp without time zone NOT NULL,
  "DT_LAST_SEEN_AT" timestamp without time zone NOT NULL,
  "NU_SPECTRUM_COUNT" bigint NOT NULL,
  "IS_OVERLAPPING" smallint NOT NULL DEFAULT 0,
  "DT_REFRESHED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("FK_HOST", "NU_VISIT")
);

CREATE TABLE "HOST_MONTHLY_METRIC" (
  "FK_HOST" integer NOT NULL,
  "DT_REFERENCE_MONTH" date NOT NULL,
  "NU_DISCOVERED_FILES" bigint NOT NULL DEFAULT 0,
  "VL_DISCOVERED_GB" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_DONE_FILES" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_DONE_GB" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_PENDING_FILES" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_PENDING_GB" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_ERROR_FILES" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_ERROR_GB" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_DONE_FILES" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_DONE_GB" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_PENDING_FILES" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_PENDING_GB" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_ERROR_FILES" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_ERROR_GB" decimal(18,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY ("FK_HOST","DT_REFERENCE_MONTH")
);

CREATE TABLE "HOST_METRIC" (
  "FK_HOST" integer NOT NULL,
  "DT_REFERENCE_MONTH" date NOT NULL,
  "NU_BACKUP_DONE_THIS_MONTH" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_DONE_GB_THIS_MONTH" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_QUEUE_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_QUEUE_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_QUEUE_RUNNING_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_QUEUE_RUNNING_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_QUEUE_SUSPENDED_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_QUEUE_SUSPENDED_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_QUEUE_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_QUEUE_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_QUEUE_RUNNING_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_QUEUE_RUNNING_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_QUEUE_FROZEN_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_QUEUE_FROZEN_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PAYLOAD_DELETED_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_PAYLOAD_DELETED_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_DONE_THIS_MONTH" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_DONE_GB_THIS_MONTH" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_DISCOVERED_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_DISCOVERED_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_DONE_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_DONE_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_DONE_FILES_TOTAL" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_DONE_GB_TOTAL" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_PENDING_FILES_CURRENT" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_PENDING_GB_CURRENT" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_ERROR_FILES_CURRENT" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_ERROR_GB_CURRENT" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_BACKUP_SUSPENDED_FILES_CURRENT" bigint NOT NULL DEFAULT 0,
  "VL_BACKUP_SUSPENDED_GB_CURRENT" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_PENDING_FILES_CURRENT" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_PENDING_GB_CURRENT" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_ERROR_FILES_CURRENT" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_ERROR_GB_CURRENT" decimal(18,2) NOT NULL DEFAULT 0.00,
  "NU_PROCESSING_FROZEN_FILES_CURRENT" bigint NOT NULL DEFAULT 0,
  "VL_PROCESSING_FROZEN_GB_CURRENT" decimal(18,2) NOT NULL DEFAULT 0.00,
  "DT_REFRESHED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("FK_HOST")
);

CREATE TABLE "HOST_ERROR_METRIC" (
  "ID_HOST_ERROR" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "FK_HOST" integer NOT NULL,
  "NA_ERROR_SCOPE" varchar(32) NOT NULL,
  "NA_TASK_STATE" varchar(16) NOT NULL,
  "NA_ERROR_CODE" varchar(64) DEFAULT NULL,
  "NA_ERROR_SUMMARY_HASH" char(64) NOT NULL,
  "NA_ERROR_SUMMARY" text DEFAULT NULL,
  "NU_ERROR_COUNT" bigint NOT NULL DEFAULT 0,
  "DT_LAST_SEEN_AT" timestamp without time zone DEFAULT NULL,
  "ID_LAST_SOURCE_ROW" bigint DEFAULT NULL,
  PRIMARY KEY ("ID_HOST_ERROR")
);

CREATE TABLE "WEBFUSION_USAGE_METRIC_MONTHLY" (
  "NA_METRIC_NAME" varchar(64) NOT NULL,
  "DT_REFERENCE_MONTH" date NOT NULL,
  "NU_VALUE" bigint NOT NULL DEFAULT 0,
  "DT_UPDATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("NA_METRIC_NAME","DT_REFERENCE_MONTH")
);

CREATE TABLE "WEBFUSION_USAGE_LOG_CHECKPOINT" (
  "NA_SOURCE_NAME" varchar(64) NOT NULL,
  "NA_LOG_PATH" varchar(255) NOT NULL,
  "NA_FILE_SIGNATURE" varchar(128) DEFAULT NULL,
  "NU_LAST_OFFSET" bigint NOT NULL DEFAULT 0,
  "NU_LAST_SIZE" bigint NOT NULL DEFAULT 0,
  "NU_LAST_MTIME_NS" bigint NOT NULL DEFAULT 0,
  "DT_UPDATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("NA_SOURCE_NAME")
);

CREATE UNIQUE INDEX summary_outbox_scope ON "SUMMARY_OUTBOX" ("NA_SCOPE_TYPE", "NA_SCOPE_VALUE");
CREATE INDEX summary_refresh_object ON "SUMMARY_REFRESH_LOG" ("NA_OBJECT_NAME", "DT_STARTED_AT" DESC);
CREATE UNIQUE INDEX host_equipment_primary ON "HOST_EQUIPMENT_LINK" ("FK_EQUIPMENT") WHERE "IS_PRIMARY_LINK" = 1;
CREATE INDEX host_equipment_equipment ON "HOST_EQUIPMENT_LINK" ("FK_EQUIPMENT", "FK_HOST");
CREATE INDEX site_equipment_equipment ON "SITE_EQUIPMENT_METRIC" ("FK_EQUIPMENT", "DT_LAST_SEEN_AT" DESC NULLS LAST, "FK_SITE");
CREATE INDEX host_visit_site ON "HOST_LOCATION_VISIT" ("FK_SITE", "FK_HOST");
CREATE INDEX host_visit_date ON "HOST_LOCATION_VISIT" ("FK_HOST", "DT_FIRST_SEEN_AT" DESC);
CREATE INDEX host_monthly_month ON "HOST_MONTHLY_METRIC" ("DT_REFERENCE_MONTH", "FK_HOST");
CREATE UNIQUE INDEX host_error_bucket ON "HOST_ERROR_METRIC" ("FK_HOST", "NA_ERROR_SCOPE", "NA_TASK_STATE", "NA_ERROR_CODE", "NA_ERROR_SUMMARY_HASH") NULLS NOT DISTINCT;
CREATE INDEX host_error_host ON "HOST_ERROR_METRIC" ("FK_HOST", "NU_ERROR_COUNT" DESC);
CREATE INDEX webfusion_usage_month ON "WEBFUSION_USAGE_METRIC_MONTHLY" ("DT_REFERENCE_MONTH", "NA_METRIC_NAME");

CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW IS DISTINCT FROM OLD AND NEW."DT_UPDATED_AT" IS NOT DISTINCT FROM OLD."DT_UPDATED_AT" THEN
    NEW."DT_UPDATED_AT" := CURRENT_TIMESTAMP;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "WEBFUSION_USAGE_METRIC_MONTHLY" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "WEBFUSION_USAGE_LOG_CHECKPOINT" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
